{
  "name": "cache-clock",
  "version": "0.1.0",
  "description": "Shows how long the prompt cache stays warm after the last model request, warns before it lapses, and flags a cache miss when one happens.",
  "types": "./types/index.d.ts",
  "userConfig": {
    "ttlMinutes": {
      "type": "number",
      "title": "Cache TTL (minutes)",
      "description": "How long the prompt cache lives after a request starts. Claude Code sessions use 60; drops to 5 under usage overage.",
      "default": 60
    },
    "warnMinutes": {
      "type": "number",
      "title": "Warn at (minutes left)",
      "description": "Show the band and a toast when this much of the window remains.",
      "default": 5
    },
    "missTokens": {
      "type": "number",
      "title": "Miss threshold (tokens)",
      "description": "A request that writes at least this many cache tokens while reading fewer than it wrote counts as a cache miss.",
      "default": 20000
    }
  }
}

